using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using Controllers.Enemy;
using Core.Channels.Game;
using Core;
using Controllers.Services;
using Controllers.Time;
using Controllers.Network;

namespace Managers
{
    public class EnemiesGenorator : MonoBehaviour
    {
        [SerializeField]
        GameObject testPrefab;

        [Header("对象池设置")]
        [SerializeField, Tooltip("专属对象池名称，多个生成器使用不同池名可避免竞争")]
        private string poolName = "";

        [SerializeField, Tooltip("该生成器专属对象池的预创建数量（骷髅敌人数量多建议 20-30）")]
        private int poolPreloadCount = 25;

        private string actualPoolName;
        private bool isPoolRegistered = false;
        private bool isPhotonReady = false;
        private float spawnInterval;
        private float updateSpawnInterval = 30f;
        private float updateSpawnIntervalCounter = 0f;
        private float timer = 0f;
        bool canGenorate = false;

        /// <summary>缓存的怪物数量监听器</summary>
        private MonsterCountMonitor _countMonitor;

        /// <summary>
        /// 最低生成间隔（秒），在 10 分钟时达到此值
        /// </summary>
        private const float MinSpawnInterval = 1.5f;

        /// <summary>
        /// 初始生成间隔（秒）
        /// </summary>
        private const float BaseSpawnInterval = 10f;

        /// <summary>
        /// 达到最低生成间隔所需时间（秒）= 10 分钟
        /// </summary>
        private const float TimeToReachMin = 600f;

        /// <summary>
        /// 回到初始生成间隔所需时间（秒）= 15 分钟
        /// </summary>
        private const float TimeToReturnToBase = 900f;

        private float QueryDifficultyCoefficient()
        {
            var query = new DifficultyCoefficientQueryData { queryType = DifficultyQueryType.GetDifficultyCoefficient };
            EventChannelLocator.MainContainer.difficultyCoefficientQueryChannel.Raise(query);
            return query.result;
        }

        void Start()
        {
            // 池名未设置时自动按 GameObject 名称生成，确保每个生成器拥有独立池
            if (string.IsNullOrEmpty(poolName))
                actualPoolName = gameObject.name + "_Pool";
            else
                actualPoolName = poolName;

            // 在对象池管理器中注册专属池（已存在则跳过）
            if (NetworkObjectPoolManager.instance != null && testPrefab != null)
            {
                NetworkObjectPoolManager.instance.RegisterPool(actualPoolName, testPrefab, poolPreloadCount);
                isPoolRegistered = true;
            }

            spawnInterval = BaseSpawnInterval;
        }

        void Update()
        {
            if (GamePauseManager.isPaused)
                return;
            if (!NetworkServiceLocator.PlayerService.IsMasterClient)
                return; // 只有房主执行生成逻辑
            if (!isPhotonReady)
            {
                if (EventChannelLocator.MainContainer.gameSettings.IsTest)
                {
                    canGenorate = true; // 测试模式：无条件允许
                }
                else
                {
                    canGenorate =
                        NetworkServiceLocator.PlayerService.IsConnectedAndInRoom;
                    if (canGenorate)
                    {
                        isPhotonReady = true;
                    }
                }
            }
            if (canGenorate)
            {
                // 定期根据游戏进度动态更新生成间隔
                UpdateSpawnInterval();

                if (timer >= spawnInterval)
                {
                    SpawnEnemy();
                    timer = 0f;
                }
                else
                {
                    timer += UnityEngine.Time.deltaTime;
                }
            }
        }

        /// <summary>
        /// 根据游戏已过时间动态更新生成间隔。
        /// 曲线：0→10min 从 10s 降到 1.5s，10→15min 从 1.5s 回到 10s。
        /// 不受难度影响。
        /// </summary>
        private void UpdateSpawnInterval()
        {
            updateSpawnIntervalCounter += UnityEngine.Time.deltaTime;
            if (updateSpawnIntervalCounter >= updateSpawnInterval)
            {
                var timeManager = ServiceLocator.Get<SyncedGameTimeManager>();
                float currentTime = timeManager.GetCurrentTime();

                if (currentTime <= TimeToReachMin)
                {
                    // 0 → 10 分钟：从 10s 线性下降到 1.5s
                    float progress = currentTime / TimeToReachMin;
                    spawnInterval = Mathf.Lerp(BaseSpawnInterval, MinSpawnInterval, progress);
                }
                else if (currentTime <= TimeToReturnToBase)
                {
                    // 10 → 15 分钟：从 1.5s 线性回到 10s
                    float progress = (currentTime - TimeToReachMin) / (TimeToReturnToBase - TimeToReachMin);
                    spawnInterval = Mathf.Lerp(MinSpawnInterval, BaseSpawnInterval, progress);
                }
                else
                {
                    // 15 分钟后：保持初始值 10s
                    spawnInterval = BaseSpawnInterval;
                }

                updateSpawnIntervalCounter = 0f;
            }
        }

        private void SpawnEnemy()
        {
            if (GamePauseManager.isPaused)
                return;
            if (!NetworkServiceLocator.PlayerService.IsMasterClient)
                return;

            // 从 MonsterCountMonitor 读取该池的数量上限，达到上限则跳过生成
            if (_countMonitor == null)
                _countMonitor = ServiceLocator.Get<MonsterCountMonitor>();

            int maxCount = _countMonitor != null
                ? _countMonitor.GetMaxCount(actualPoolName)
                : -1;

            if (maxCount > 0)
            {
                int currentCount = _countMonitor.GetCount(actualPoolName);
                if (currentCount >= maxCount)
                {
                    // 已达到上限，跳过本次生成
                    return;
                }
            }

            if (!isPoolRegistered)
            {
                Debug.LogWarning($"[EnemiesGenorator] {gameObject.name} 对象池未注册，尝试延迟注册");
                if (NetworkObjectPoolManager.instance != null && testPrefab != null)
                {
                    NetworkObjectPoolManager.instance.RegisterPool(actualPoolName, testPrefab, poolPreloadCount);
                    isPoolRegistered = true;
                }
                else
                    return;
            }

            // 使用专属对象池生成敌人，避免多个生成器竞争同一池
            EventChannelLocator.MainContainer.poolOperationChannel.Raise(
                PoolOperationData.CreateSpawn(actualPoolName, transform.position, Quaternion.identity, null));
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using Controllers.Character;
using Core;
using Core.Channels.Combat;
using Controllers.Player;
using Core;
using Controllers.PowerUp;
using Controllers.Services;
using NetworkTarget = Controllers.Network.NetworkTarget;
using Controllers.Network;
using UnityEngine;
using UnityEngine.AI;
using Managers;

namespace Controllers.Enemy
{
  public class EnemyBase : MonoBehaviour
  {
    [Header("纯数据")]
    [SerializeField]
    protected EnemyData enemyData;

    [Header("事件通道")]
    [SerializeField] private DamageEventChannelSO damageEventChannel;

    [SerializeField] protected NetworkIdentityBase _network;


    protected Collider[] colliders;

    [SerializeField]
    protected Animator animator;

    [SerializeField]
    protected Rigidbody rb;

    [SerializeField]
    protected GameObject PlayerTarget;


    protected virtual void Awake()
    {
      enemyData = new EnemyData(new AttributeEnemyBase(500, 500, 50, 2));
      colliders = GetComponentsInChildren<Collider>();
      if (_network == null)
        _network = GetComponent<NetworkIdentityBase>();

      if (rb == null)
        rb = GetComponent<Rigidbody>();
      if (animator == null)
        animator = GetComponent<Animator>();
    }

    protected virtual void Start()
    {
      InitializeEnemy();
    }

    // 初始化方法，从池中取出时也会调用
    protected virtual void InitializeEnemy()
    {
      if (!enemyData.isInitialized)
      {
        enemyData.isInitialized = true;
      }
      TransitionToState(EnemyState.Idle);
    }

    protected virtual void Update()
    {
      if (GamePauseManager.isPaused)
        return;
      // 如果已死亡，不执行更新逻辑
      if (enemyData.currentState == EnemyState.Die)
      {
        return;
      }

      // 只有拥有者（Master Client）执行AI逻辑和移动
      // 其他客户端通过Photon网络同步获取位置和动画
      // 测试模式下无Photon网络，直接执行
      if (!EventChannelLocator.MainContainer.gameSettings.IsTest && !_network.IsMine)
      {
        return;
      }

      switch (enemyData.currentState)
      {
        case EnemyState.Idle:
          UpdateIdle();
          break;
        case EnemyState.Run:
          UpdateRun();
          break;
        case EnemyState.Attack:
          UpdateAttack();
          break;
        case EnemyState.Die:
          UpdateDie();
          break;
      }
    }

    //追踪最近的玩家
    protected virtual void TrackPlayer()
    {
      if (GetIsDie() || enemyData.currentState == EnemyState.Die)
      {
        // 停止物理移动
        if (rb != null)
        {
          rb.velocity = Vector3.zero;
          rb.angularVelocity = Vector3.zero;
        }
        return;
      }

      // 从 PlayerManager 获取缓存的玩家列表，避免每帧 FindGameObjectsWithTag
      IReadOnlyList<GameObject> players =
          PlayerManager.instance != null ? PlayerManager.instance.ActivePlayerObjects : null;

      if (players == null || players.Count == 0)
      {
        PlayerTarget = null;
        return;
      }

      PlayerTarget = players[0];
      for (int i = 1; i < players.Count; i++)
      {
        if (players[i] == null)
          continue;
        if (
            PlayerTarget == null
            || Vector3.Distance(transform.position, players[i].transform.position)
                < Vector3.Distance(transform.position, PlayerTarget.transform.position)
        )
        {
          PlayerTarget = players[i];
        }
      }
    }

    #region 状态机相关代码
    protected virtual void TransitionToState(EnemyState newState)
    {
      // 退出当前状态
      switch (enemyData.currentState)
      {
        case EnemyState.Idle:
          ExitIdle();
          break;
        case EnemyState.Run:
          ExitRun();
          break;
        case EnemyState.Attack:
          ExitAttack();
          break;
        case EnemyState.Die:
          ExitDie();
          break;
      }

      enemyData.currentState = newState;

      // 进入新状态
      switch (enemyData.currentState)
      {
        case EnemyState.Idle:
          EnterIdle();
          break;
        case EnemyState.Run:
          EnterRun();
          break;
        case EnemyState.Attack:
          EnterAttack();
          break;
        case EnemyState.Die:
          EnterDie();
          break;
      }
    }

    // ========== Idle状态 ==========
    protected virtual void EnterIdle()
    {
      TrackPlayer();
      if (animator != null)
      {
        animator.SetBool("isRun", false);
      }
    }

    protected virtual void UpdateIdle()
    {
      if (PlayerTarget)
      {
        TransitionToState(EnemyState.Run);
      }
      else
      {
        TrackPlayer();
        return;
      }
    }

    protected virtual void ExitIdle() { }

    // ========== Run状态 ==========
    protected virtual void EnterRun()
    {
      if (animator != null)
      {
        animator.SetBool("isRun", true);
      }
    }

    protected virtual void UpdateRun()
    {
      if (!PlayerTarget)
      {
        TransitionToState(EnemyState.Idle);
      }
      else
      {
        // 计算移动向量
        Vector3 moveDirection = (
            PlayerTarget.transform.position - transform.position
        ).normalized;
        // 移动敌人
        if (rb != null)
        {
          rb.MovePosition(
              transform.position + moveDirection * enemyData.attribute.moveSpeed * UnityEngine.Time.deltaTime
          );
        }
        // 旋转敌人朝向玩家,只在xz轴上旋转
        if (PlayerTarget != null)
        {
          transform.LookAt(
              new Vector3(
                  PlayerTarget.transform.position.x,
                  transform.position.y,
                  PlayerTarget.transform.position.z
              )
          );
        }
      }
    }

    protected virtual void ExitRun()
    {
      if (animator != null)
      {
        animator.SetBool("isRun", false);
      }
    }

    // ========== Attack状态 ==========
    protected virtual void EnterAttack() { }

    protected virtual void UpdateAttack() { }

    protected virtual void ExitAttack() { }

    // ========== Die状态 ==========
    protected virtual void EnterDie()
    {
      EventChannelLocator.MainContainer.enemyReportChannel.Raise(new EnemyReportData(transform.position, _network.ViewID));

      // 记录本次击杀到对局统计
      MatchStatisticsManager.Instance?.RecordKill();

      // 停止物理移动
      if (rb != null)
      {
        rb.velocity = Vector3.zero;
        rb.angularVelocity = Vector3.zero;
        rb.isKinematic = true;
      }

      // 停止 NavMeshAgent（所有怪物类型通用，即使子类不继承 AttackableEnemy）
      var navAgent = GetComponent<NavMeshAgent>();
      if (navAgent != null && navAgent.isActiveAndEnabled)
      {
        navAgent.isStopped = true;
        if (navAgent.isOnNavMesh)
          navAgent.ResetPath();
      }

      // 禁用所有 Collider（所有客户端都执行）
      // 注意：之前非房主端不禁用 Collider 是因为 AttackRange 依赖 OnTriggerStay 检测死亡，
      // 现在已经改用 IsDeadOrDying() 方法通过状态机判断死亡，不再依赖 Collider 状态
      foreach (Collider collider in colliders)
      {
        collider.enabled = false;
      }

      if (animator != null)
      {
        animator.SetTrigger("die");
        animator.Update(0f); // 强制立即触发动画过渡，修复非房主端死亡动画不播放的问题
      }

      DropExperience();

      // 使用对象池回收而不是直接销毁
      Invoke(nameof(ReturnToPool), 3f);
    }

    protected virtual void UpdateDie() { }

    protected virtual void ExitDie() { }
    #endregion

    // 返回对象池（子类可重写以指定池名）
    protected virtual void ReturnToPool()
    {
      if (EventChannelLocator.MainContainer.gameSettings.IsTest)
      {
        // 测试模式：直接本地回池
        EventChannelLocator.MainContainer.poolOperationChannel.Raise(
            PoolOperationData.CreateDespawn(GetPoolName(), gameObject));
        return;
      }

      if (_network.IsMasterClient)
      {
        // 房主端：PhotonNetwork.Destroy 同步到所有客户端
        EventChannelLocator.MainContainer.poolOperationChannel.Raise(
            PoolOperationData.CreateDespawn(GetPoolName(), gameObject));
      }
      else
      {
        // 非房主端：通知房主销毁此怪物（处理房主端未检测到死亡的情况）
        NetworkServiceLocator.DomainRpcService?.InvokeRPC(
            "RPC_RequestEnemyDestroy",
            NetworkTarget.MasterClient,
            _network.ViewID);
        // 本地立即禁用，不等网络同步
        gameObject.SetActive(false);
      }
    }

    // 获取对象池名称（子类重写以指定自己所属的池）
    protected virtual string GetPoolName()
    {
      return PoolConst.Skeleton;
    }

    public virtual EnemyState GetCurrentState()
    {
      return enemyData.currentState;
    }

    public virtual bool GetIsDie()
    {
      // ★ 非房主客户端：不依赖本地死亡状态（isDead），避免 AttackRange 误判后移除目标
      // 非房主只负责显示伤害数字和扣血效果，不参与死亡判定
      // 房主销毁怪物时 PhotonNetwork.Destroy 会同步到所有客户端，届时怪物自然被移除
      if (!EventChannelLocator.MainContainer.gameSettings.IsTest
          && _network != null
          && !_network.IsMasterClient)
      {
        return false;
      }
      return enemyData.attribute.GetIsDie();
    }

    /// <summary>
    /// 判断敌人是否真正死亡（对所有客户端生效）
    /// 与 GetIsDie() 的区别：非房主端也会检查状态机，适用于弹道/投射物的死亡检测
    /// </summary>
    public bool IsDeadOrDying()
    {
      return GetIsDie() || enemyData.currentState == EnemyState.Die;
    }

    protected virtual void OnEnable()
    {
      // 从对象池取出时重新初始化
      if (enemyData.isInitialized)
      {
        // [修复-问题四] 调用 ResetState 确保对象池回收后的状态被完全重置
        // 包括：物理(isKinematic)/碰撞体/动画/属性(isDead/currentHealth)/目标等
        ResetState();

        // 确保属性不为 null（[NonSerialized] 字段在序列化后可能丢失）
        if (enemyData.attribute == null)
        {
          enemyData.attribute = new AttributeEnemyBase(500, 500, 50, 2);
        }

        InitializeEnemy();
      }

      // [修复] 每次 OnEnable 都重新获取事件通道，避免第一次获取失败后永久缓存 null
      damageEventChannel = EventChannelLocator.MainContainer?.damageEventChannel;
      if (damageEventChannel != null)
      {
        damageEventChannel.RegisterListener(OnDamageReceived);
      }
      else
      {
        Debug.LogWarning($"[EnemyBase] {gameObject.name} 无法获取 damageEventChannel，将无法收到伤害事件", this);
      }
    }

    protected virtual void OnDisable()
    {
      // 取消所有Invoke调用
      CancelInvoke();

      // 停止所有协程
      StopAllCoroutines();
      damageEventChannel?.UnregisterListener(OnDamageReceived);
    }


    protected virtual void OnDamageReceived(EventArgsBase args)
    {
      // 空引用检查：确保 attribute 不为 null
      if (enemyData.attribute == null)
      {
        Debug.LogWarning(
            $"[EnemyBase] OnDamageReceived: attribute 为空，敌人对象: {gameObject.name}"
        );
        return;
      }

      if (enemyData.attribute.GetIsDie())
      {
        return;
      }
      DamageEventArgs damageEventArgs = args as DamageEventArgs;
      if (damageEventArgs == null)
      {
        Debug.LogWarning($"期望 DamageEventArgs，但收到 {args?.GetType()}");
        return;
      }
      if (damageEventArgs.damgeTarget != gameObject)
      {
        return;
      }
      TakeDamage(damageEventArgs);
    }

    public virtual void TakeDamage(DamageEventArgs damageEventArgs)
    {
      if (enemyData.attribute.GetIsDie())
      {
        return;
      }
      damageEventArgs.CalculateFinalDamageValue();
      damageEventArgs.finalDamageValue = Mathf.Ceil(damageEventArgs.finalDamageValue);
      enemyData.attribute.TakeDamage(damageEventArgs.finalDamageValue);

      // 记录本次伤害到对局统计
      MatchStatisticsManager.Instance?.RecordDamage(Mathf.RoundToInt(damageEventArgs.finalDamageValue));
      QuestTaskManager.Instance?.RecordDamage(Mathf.RoundToInt(damageEventArgs.finalDamageValue));

      Debug.Log(
          "最终伤害为："
              + damageEventArgs.finalDamageValue
              + "是否死亡:"
              + enemyData.attribute.GetIsDie()
      );
      if (EventChannelLocator.MainContainer.gameSettings.IsTest)
      {
        EventChannelLocator.MainContainer.combat.damageDisplayChannel?.Raise(
            DamageDisplayEventArgs.GetShared(
                damageEventArgs.finalDamageValue,
                transform.position,
                damageEventArgs.isCritical
            )
        );
      }
      enemyData.attribute.TakeDamageSpecial(damageEventArgs.element);

      if (enemyData.attribute.GetIsDie())
      {
        TransitionToState(EnemyState.Die);
      }
    }

    //死亡后掉落经验
    protected virtual void DropExperience()
    {
      Debug.Log("敌人死亡，掉落经验");

      // 10%概率掉落道具
      if (Random.value <= 0.1f && PowerUpManager.Instance != null)
      {
        PowerUpManager.Instance.SpawnRandomPowerUp(transform.position);
        Debug.Log("[PowerUp] 敌人掉落道具！");
      }
    }

    // 重置状态（对象池回收时调用）
    public virtual void ResetState()
    {
      // 恢复刚体状态
      if (rb != null)
      {
        rb.isKinematic = false;
      }

      foreach (Collider collider in colliders)
      {
        collider.enabled = true;
      }

      // 1. 取消所有Invoke和协程
      CancelInvoke();
      StopAllCoroutines();

      // 2. 重置状态机
      if (enemyData.currentState == EnemyState.Die)
      {
        CancelInvoke(nameof(ReturnToPool));
      }
      enemyData.currentState = EnemyState.Idle;

      // 3. 重置动画
      if (animator != null)
      {
        animator.ResetTrigger("die");
        animator.SetBool("isRun", false);
        animator.Rebind(); // 重置所有动画状态
        animator.Update(0f); // 立即更新动画
      }

      // 4. 重置物理
      if (rb != null)
      {
        rb.velocity = Vector3.zero;
        rb.angularVelocity = Vector3.zero;
      }

      // 5. 重置属性
      if (enemyData.attribute != null)
      {
        enemyData.attribute.ResetAttribute();
      }

      // 6. 清除目标
      PlayerTarget = null;

      // 7. 重置数据类的运行时状态
      enemyData?.ResetRuntimeState();
    }
  }
}

using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using UnityEngine;
using Debug = UnityEngine.Debug;

namespace Controllers.Character
{
    public class AttributeEnemyBase
    {
        //基本属性
        public float maxHealth;
        public float currentHealth;
        public float attackPower;
        public float moveSpeed;
        public bool isDead = false;

        public AttributeEnemyBase(
            float maxHealth,
            float currentHealth,
            float attackPower,
            float moveSpeed
        )
        {
            this.maxHealth = maxHealth;
            this.currentHealth = currentHealth;
            this.attackPower = attackPower;
            this.moveSpeed = moveSpeed;
            isDead = false;
        }

        public virtual bool GetIsDie()
        {
            return isDead;
        }

        public virtual void SetIsDie(bool value)
        {
            isDead = value;
        }

        //减少生命的方法
        public virtual void TakeDamage(float damage)
        {
            currentHealth -= damage;
            Debug.Log("当前生命值: " + currentHealth + " / " + maxHealth);
            if (currentHealth <= 0)
            {
                Die();
            }
        }

        //减少最大生命值的方法
        public virtual void TakeDamageMaxHealth(float damage)
        {
            maxHealth -= damage;
            if (maxHealth <= 0)
            {
                maxHealth = 0;
            }
        }

        public virtual void SetMaxHealth(float newMaxHealth)
        {
            maxHealth = newMaxHealth;
            currentHealth = maxHealth;
        }

        //受到特殊伤害的方法
        public virtual void TakeDamageSpecial(Element element)
        {
            //待写
            switch (element)
            {
                case Element.Grass:

                    break;
                case Element.Winter:

                    break;
                case Element.Lightning:

                    break;
                default:
                    break;
            }
        }

        public virtual void SetAttackPower(float newAttackPower)
        {
            attackPower = newAttackPower;
        }

        public virtual void SetMoveSpeed(float newMoveSpeed)
        {
            moveSpeed = newMoveSpeed;
        }

        public virtual void Die()
        {
            SetIsDie(true);
        }

        public virtual void Heal(float health)
        {
            currentHealth += health;
            if (currentHealth > maxHealth)
            {
                currentHealth = maxHealth;
            }
        }

        public virtual void ResetHealth()
        {
            currentHealth = maxHealth;
        }

        public float GetAttackPower()
        {
            return attackPower;
        }

        public void ResetAttribute()
        {
            currentHealth = maxHealth;
            isDead = false;
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using NetworkTarget = Controllers.Network.NetworkTarget;
using System.Linq;
using Managers;
using Controllers.Services;
using Controllers.Time;
using UnityEngine;
using DG.Tweening;
using Core;
using Core.Channels.Game;
using Photon.Pun;

namespace Controllers.Time
{
    /// <summary>
    /// 全局游戏时间管理器（支持Photon PUN2联机同步）
    /// 核心逻辑层：仅处理时间计算、事件触发、网络同步
    /// UI相关代码已剥离至Presentation层
    /// </summary>
    public class SyncedGameTimeManager : MonoBehaviour
    {
        [Header("时间设置")]
        [Tooltip("总游戏时间（秒）")]
        public float totalGameTime = 1800f;

        [Tooltip("是否启用网络同步（非主机/房主跟随主机时间）")]
        public bool isSynced = true;

        [Tooltip("是否循环播放（时间结束后重置）")]
        public bool loop = false;

        [Header("事件列表（数据驱动）")]
        [SerializeField]
        private TimeEventListSO timeEventList;

        /// <summary>运行时事件列表（从 SO 加载副本，支持运行时增删）</summary>
        public List<TimeEventData> timeEvents = new List<TimeEventData>();

        [Header("最终Boss设置")]
        [SerializeField]
        private string bossName = "Boss_Horror";
        private bool isBossGenerated = false;

        // 运行时数据
        private float currentTime = 0f;
        private float lastTriggerTime = 0f;
        private bool isRunning = false;
        private HashSet<string> triggeredEventIds = new HashSet<string>();

        // 事件触发委托
        public Action<TimeEventData> OnTimeEventTriggered;
        public Action<float> OnTimeUpdated;
        public Action OnGameTimeFinished;
        public Action OnGameTimeLoop;

        private float originDifficultyCoefficient = 1f;

        /// <summary>
        /// 单例实例引用（供静态Handler方法使用）
        /// </summary>
        public static SyncedGameTimeManager Instance { get; private set; }

        void Awake()
        {
            Instance = this;
            ServiceLocator.Register(this);
            DomainServiceLocator.Register(this);

            // 从 ScriptableObject 加载事件列表副本
            if (timeEventList != null)
            {
                timeEvents = timeEventList.GetEvents();
                Debug.Log($"[SyncedGameTimeManager] 从 {timeEventList.name} 加载了 {timeEvents.Count} 个时间事件");
            }
            else
            {
                Debug.LogWarning("[SyncedGameTimeManager] timeEventList 未赋值，使用空的运行时列表");
                timeEvents = new List<TimeEventData>();
            }
        }

        void Start()
        {
            if (NetworkServiceLocator.PlayerService.IsMasterClient)
            {
                NetworkServiceLocator.DomainRpcService?.InvokeRPC("RPC_SyncStartCaTime", NetworkTarget.All);
            }
        }

        void OnEnable()
        {
            if (EventChannelLocator.MainContainer.timeQueryChannel != null)
            {
                EventChannelLocator.MainContainer.timeQueryChannel.RegisterListener(OnTimeQuery);
            }
            if (EventChannelLocator.MainContainer.pauseChannel != null)
            {
                EventChannelLocator.MainContainer.pauseChannel.RegisterListener(OnGamePauseChanged);
            }
        }

        void OnDisable()
        {
            if (EventChannelLocator.MainContainer.timeQueryChannel != null)
            {
                EventChannelLocator.MainContainer.timeQueryChannel.UnregisterListener(OnTimeQuery);
            }
            if (EventChannelLocator.MainContainer.pauseChannel != null)
            {
                EventChannelLocator.MainContainer.pauseChannel.UnregisterListener(OnGamePauseChanged);
            }
        }

        /// <summary>
        /// 响应 TimeQueryEventChannelSO 的查询请求
        /// </summary>
        private void OnTimeQuery(TimeQueryData data)
        {
            data.currentTime = currentTime;
            data.normalizedTime = GetNormalizedTime();
            data.totalGameTime = totalGameTime;
            data.remainingTime = GetRemainingTime();
            data.isTimeRunning = isRunning;
        }

        /// <summary>
        /// 响应 pauseChannel — 选择卡片/升级面板打开时暂停计时
        /// </summary>
        private void OnGamePauseChanged(bool isPaused)
        {
            isRunning = !isPaused;
        }

        // ---- 静态 Handler 方法（供 DomainRpcBridge 调用） ----

        /// <summary>
        /// 由 DomainRpcBridge.RPC_SyncStartCaTime 调用
        /// </summary>
        public static void HandleSyncStartCaTime()
        {
            if (Instance != null) Instance.StartGameTime();
        }

        /// <summary>
        /// 由 DomainRpcBridge.RPC_OnTimeEventTriggered 调用
        /// </summary>
        public static void HandleOnTimeEventTriggered(string eventId, float triggerTime)
        {
            if (Instance == null) return;
            if (!NetworkServiceLocator.PlayerService.IsMasterClient)
            {
                var timeEvent = Instance.timeEvents.Find(e => e.eventId == eventId);
                if (timeEvent != null && !timeEvent.isTriggered)
                {
                    timeEvent.isTriggered = true;
                    Instance.triggeredEventIds.Add(eventId);
                    Instance.TriggerEvent(timeEvent);
                }
            }
        }

        /// <summary>
        /// 由 DomainRpcBridge.RPC_GameTimeFinished 调用
        /// </summary>
        public static void HandleGameTimeFinished()
        {
            if (Instance == null) return;
            Instance.isRunning = false;
            Instance.OnGameTimeFinished?.Invoke();
            EventChannelLocator.MainContainer.gameStateChangeChannel.Raise(GameState.GameOver);
        }

        /// <summary>
        /// 由 DomainRpcBridge.RPC_BossSpawn 调用
        /// 非主机客户端收到通知后，触发本地事件通道 → UI 更新
        /// </summary>
        public static void HandleBossSpawn(string bossName)
        {
            if (Instance == null) return;
            if (!NetworkServiceLocator.PlayerService.IsMasterClient)
            {
                Instance.isBossGenerated = true;
                EventChannelLocator.MainContainer.bossSpawnChannel.Raise(bossName);
            }
        }

        /// <summary>
        /// 由 DomainRpcBridge.RPC_SyncSetTime 调用
        /// </summary>
        public static void HandleSyncSetTime(float time)
        {
            if (Instance == null) return;
            if (!NetworkServiceLocator.PlayerService.IsMasterClient)
            {
                Instance.currentTime = Mathf.Clamp(time, 0, Instance.totalGameTime);

                // 同步后刷新 UI（校正本地漂移）
                Instance.OnTimeUpdated?.Invoke(Instance.currentTime);
                var args = new TimeEventArgs(null, Instance.currentTime);
                EventChannelLocator.MainContainer.timeEventChannel.Raise(args);
            }
        }

        /// <summary>
        /// 由 DomainRpcBridge.RPC_SyncStartTime 调用
        /// </summary>
        public static void HandleSyncStartTime()
        {
            if (Instance == null) return;
            if (!NetworkServiceLocator.PlayerService.IsMasterClient)
            {
                Instance.isRunning = true;
                EventChannelLocator.MainContainer.timeStartedChannel.Raise();

                // 立即刷新 UI（显示当前时间）
                Instance.OnTimeUpdated?.Invoke(Instance.currentTime);
                var args = new TimeEventArgs(null, Instance.currentTime);
                EventChannelLocator.MainContainer.timeEventChannel.Raise(args);
            }
        }

        /// <summary>
        /// 由 DomainRpcBridge.RPC_SyncPauseTime 调用
        /// </summary>
        public static void HandleSyncPauseTime()
        {
            if (Instance == null) return;
            if (!NetworkServiceLocator.PlayerService.IsMasterClient)
            {
                Instance.isRunning = false;
                EventChannelLocator.MainContainer.timePausedChannel.Raise();

                // 暂停时刷新 UI（显示暂停瞬间的时间）
                Instance.OnTimeUpdated?.Invoke(Instance.currentTime);
                var args = new TimeEventArgs(null, Instance.currentTime);
                EventChannelLocator.MainContainer.timeEventChannel.Raise(args);
            }
        }

        /// <summary>
        /// 由 DomainRpcBridge.RPC_SyncResetTime 调用
        /// </summary>
        public static void HandleSyncResetTime()
        {
            if (Instance == null) return;
            if (!NetworkServiceLocator.PlayerService.IsMasterClient)
            {
                Instance.currentTime = 0f;
                Instance.triggeredEventIds.Clear();
                foreach (var evt in Instance.timeEvents)
                {
                    evt.isTriggered = false;
                }
                EventChannelLocator.MainContainer.timeResetChannel.Raise();

                // 重置后刷新 UI
                Instance.OnTimeUpdated?.Invoke(Instance.currentTime);
                var args = new TimeEventArgs(null, Instance.currentTime);
                EventChannelLocator.MainContainer.timeEventChannel.Raise(args);
            }
        }

        void Update()
        {
            if (!isRunning)
                return;

            var playerService = NetworkServiceLocator.PlayerService;
            bool isLocalAuthority = !isSynced
                                 || !playerService.IsConnectedAndInRoom
                                 || playerService.IsMasterClient;

            // ── 所有客户端都本地累加时间（非房主仅用于 UI 显示，RPC 同步时校正漂移） ──
            currentTime += UnityEngine.Time.deltaTime;

            // ── 只有权威端（主机/单机）才检查时间到点、事件触发等逻辑 ──
            if (isLocalAuthority)
            {
                if (currentTime >= totalGameTime)
                {
                    if (loop)
                    {
                        currentTime = 0f;
                        triggeredEventIds.Clear();
                        foreach (var evt in timeEvents)
                        {
                            evt.isTriggered = false;
                        }

                        OnGameTimeLoop?.Invoke();

                        if (playerService.IsConnectedAndInRoom && playerService.IsMasterClient && isSynced)
                        {
                            NetworkServiceLocator.DomainRpcService?.InvokeRPC("RPC_SyncResetTime", NetworkTarget.All);
                        }
                    }
                    else
                    {
                        currentTime = totalGameTime;
                        isRunning = false;
                        OnGameTimeFinished?.Invoke();

                        if (playerService.IsConnectedAndInRoom && playerService.IsMasterClient && isSynced)
                        {
                            NetworkServiceLocator.DomainRpcService?.InvokeRPC("RPC_GameTimeFinished", NetworkTarget.All);
                        }
                    }
                }

                // 检查事件触发
                CheckAndTriggerEvents();

                // 每隔 60 秒触发敌人属性变化
                if (currentTime - lastTriggerTime >= 60f)
                {
                    lastTriggerTime = currentTime;
                    EventChannelLocator.MainContainer.timeChangeEnemyAttributeChannel.Raise(currentTime);
                }

                // 生成最终 Boss
                if (currentTime >= totalGameTime - 900f && !isBossGenerated)
                {
                    isBossGenerated = true;
                    EventChannelLocator.MainContainer.bossSpawnChannel.Raise(bossName);

                    if (playerService.IsMasterClient && isSynced)
                    {
                        NetworkServiceLocator.DomainRpcService?.InvokeRPC(
                            "RPC_BossSpawn", NetworkTarget.Others, bossName);
                    }
                }
            }

            // ── 所有客户端都触发时间更新事件（UI 刷新用） ──
            OnTimeUpdated?.Invoke(currentTime);

            var timeArgs = new TimeEventArgs(null, currentTime);
            EventChannelLocator.MainContainer.timeEventChannel.Raise(timeArgs);
        }

        void CheckAndTriggerEvents()
        {
            var playerService = NetworkServiceLocator.PlayerService;

            foreach (var timeEvent in timeEvents)
            {
                if (
                    currentTime >= timeEvent.triggerTime
                    && !triggeredEventIds.Contains(timeEvent.eventId)
                )
                {
                    if (timeEvent.once && timeEvent.isTriggered)
                        continue;

                    TriggerEvent(timeEvent);

                    if (timeEvent.once)
                    {
                        timeEvent.isTriggered = true;
                        triggeredEventIds.Add(timeEvent.eventId);

                        if (playerService.IsConnectedAndInRoom && playerService.IsMasterClient && isSynced)
                        {
                            NetworkServiceLocator.DomainRpcService?.InvokeRPC(
                                "RPC_OnTimeEventTriggered",
                                NetworkTarget.All,
                                timeEvent.eventId,
                                currentTime
                            );
                        }
                    }
                }
            }
        }

        void TriggerEvent(TimeEventData timeEvent)
        {
            Debug.Log(
                $"[TimeManager] 事件触发: {timeEvent.eventName} 时间: {FormatTime(currentTime)}"
            );

            OnTimeEventTriggered?.Invoke(timeEvent);

            var args = new TimeEventArgs
            {
                eventData = timeEvent,
                currentTime = currentTime,
                isFromNetwork = false,
            };
            EventChannelLocator.MainContainer.timeEventChannel.Raise(args);
        }

        // GenerateFinalBoss 逻辑已迁移至 Update 中的事件通道方式
        // 由 bossSpawnChannel.Raise(bossName) 触发，BossSpawner 监听处理

        #region 公共控制方法

        public void StartGameTime()
        {
            var playerService = NetworkServiceLocator.PlayerService;

            if (!playerService.IsConnectedAndInRoom || playerService.IsMasterClient || !isSynced)
            {
                isRunning = true;
                if (playerService.IsConnectedAndInRoom && playerService.IsMasterClient && isSynced)
                {
                    NetworkServiceLocator.DomainRpcService?.InvokeRPC("RPC_SyncStartTime", NetworkTarget.Others);
                }
                EventChannelLocator.MainContainer.timeStartedChannel.Raise();
            }
        }

        public void PauseGameTime()
        {
            var playerService = NetworkServiceLocator.PlayerService;

            if (!playerService.IsConnectedAndInRoom || playerService.IsMasterClient || !isSynced)
            {
                isRunning = false;
                if (playerService.IsConnectedAndInRoom && playerService.IsMasterClient && isSynced)
                {
                    NetworkServiceLocator.DomainRpcService?.InvokeRPC("RPC_SyncPauseTime", NetworkTarget.Others);
                }
                EventChannelLocator.MainContainer.timePausedChannel.Raise();
            }
        }

        public void ResumeGameTime() => StartGameTime();

        public void ResetGameTime()
        {
            var playerService = NetworkServiceLocator.PlayerService;

            if (!playerService.IsConnectedAndInRoom || playerService.IsMasterClient || !isSynced)
            {
                currentTime = 0f;
                triggeredEventIds.Clear();
                foreach (var evt in timeEvents)
                {
                    evt.isTriggered = false;
                }

                if (playerService.IsConnectedAndInRoom && playerService.IsMasterClient && isSynced)
                {
                    NetworkServiceLocator.DomainRpcService?.InvokeRPC("RPC_SyncResetTime", NetworkTarget.All);
                }
                EventChannelLocator.MainContainer.timeResetChannel.Raise();
            }
        }

        public void SetTime(float time)
        {
            var playerService = NetworkServiceLocator.PlayerService;

            time = Mathf.Clamp(time, 0f, totalGameTime);
            if (!playerService.IsConnectedAndInRoom || playerService.IsMasterClient || !isSynced)
            {
                currentTime = time;
                if (playerService.IsConnectedAndInRoom && playerService.IsMasterClient && isSynced)
                {
                    NetworkServiceLocator.DomainRpcService?.InvokeRPC("RPC_SyncSetTime", NetworkTarget.Others, time);
                }
            }
        }

        public void AddTimeEvent(TimeEventData timeEvent)
        {
            timeEvents.Add(timeEvent);
        }

        public void RemoveTimeEvent(string eventId)
        {
            var evt = timeEvents.Find(e => e.eventId == eventId);
            if (evt != null)
            {
                timeEvents.Remove(evt);
            }
        }

        public float GetCurrentTime() => currentTime;

        public float GetNormalizedTime() => currentTime / totalGameTime;

        public bool IsTimeRunning() => isRunning;

        public float GetRemainingTime() => Mathf.Max(0, totalGameTime - currentTime);

        public string FormatTime(float seconds)
        {
            TimeSpan t = TimeSpan.FromSeconds(seconds);
            if (totalGameTime >= 3600)
                return string.Format("{0:D2}:{1:D2}:{2:D2}", t.Hours, t.Minutes, t.Seconds);
            else
                return string.Format("{0:D2}:{1:D2}", t.Minutes, t.Seconds);
        }

        public float GetTotalGameTime() => totalGameTime;

        public bool GetIsGenerated() => isBossGenerated;
        #endregion
    }
}

using System.Collections;
using System.Collections.Generic;
